<script setup lang="ts">
import { getDisplayedMessageText } from '@/logic/message-display';
import { lazyStrings } from '@/strings';
import type { ChatId, MessageId } from '@/01-models/ids';
import { idToRaw } from '@/01-models/ids';
import { computed, nextTick, ref, watch } from 'vue';
import { EyeIcon, ListIcon, XIcon } from 'lucide-vue-next';
import type { ChatFlowItem } from '@/composables/useChatDisplayFlow';
import type { MessageNode } from '@/01-models/types';
import { scrollIntoViewSafe } from '@/utils/dom';
import MessageItem from './MessageItem.vue';


type OutlineVisibility = 'hidden' | 'visible';
type OutlineRole = MessageNode['role'];
type ScrollHintVisibility = 'hidden' | 'visible';

const props = defineProps<{
  chatId: ChatId,
  visibility: OutlineVisibility,
  flowItems: ChatFlowItem[],
  initialMessageId?: MessageId,
}>();

const emit = defineEmits<{
  (e: 'close'): void,
  (e: 'select-message', messageId: MessageId): void,
}>();

const peekMessageId = ref<MessageId | undefined>(undefined);
const outlineBody = ref<HTMLElement | null>(null);
const topScrollHintVisibility = ref<ScrollHintVisibility>('hidden');
const bottomScrollHintVisibility = ref<ScrollHintVisibility>('hidden');

const outlineItems = computed(() => {
  const includedMessageIds = new Set<MessageId>();
  return props.flowItems.flatMap(item => {
    if (item.type !== 'message' || item.mode !== 'content' || includedMessageIds.has(item.node.id)) return [];
    includedMessageIds.add(item.node.id);
    // The outline navigates messages, while the main display navigates their parts.
    const partContent = (() => {
      switch (item.node.role) {
      case 'assistant': return getDisplayedMessageText({ message: item.node });
      case 'user':
      case 'system':
      case 'tool': return item.partContent ?? getDisplayedMessageText({ message: item.node });
      default: { const _ex: never = item.node; throw new Error(`Unhandled outline message: ${_ex}`); }
      }
    })();
    const preview = partContent.replace(/\s+/g, ' ').trim();
    return [{
      id: item.node.id,
      role: item.node.role,
      node: item.node,
      partContent,
      preview: preview || lazyStrings.ConversationOutlineOverlay__empty_message(),
      index: includedMessageIds.size,
    }];
  });
});

watch([() => props.chatId, () => props.visibility, outlineItems], ([chatId, visibility, items], [previousChatId]) => {
  if (chatId !== previousChatId || visibility === 'hidden' || !items.some(item => item.id === peekMessageId.value)) {
    peekMessageId.value = undefined;
  }
});

const outlineMaxHeightClass = computed(() => {
  return peekMessageId.value === undefined ? "max-h-[55vh]" : "max-h-[80vh]";
});

const outlineBodyMaxHeightClass = computed(() => {
  return peekMessageId.value === undefined ? "max-h-[calc(55vh-41px)]" : "max-h-[calc(80vh-41px)]";
});

function updateScrollHints() {
  const body = outlineBody.value;
  if (!body) {
    topScrollHintVisibility.value = 'hidden';
    bottomScrollHintVisibility.value = 'hidden';
    return;
  }

  topScrollHintVisibility.value = body.scrollTop > 1 ? 'visible' : 'hidden';
  bottomScrollHintVisibility.value = body.scrollTop + body.clientHeight < body.scrollHeight - 1 ? 'visible' : 'hidden';
}

function scrollToInitialMessage() {
  const body = outlineBody.value;
  const initialMessageId = props.initialMessageId;
  if (!body || !initialMessageId) {
    updateScrollHints();
    return;
  }

  const rows = Array.from(body.querySelectorAll('[data-outline-message-id]'));
  const target = rows.find((row) => {
    if (!(row instanceof HTMLElement)) return false;
    return row.dataset.outlineMessageId === idToRaw({ id: initialMessageId });
  });

  if (target instanceof HTMLElement) {
    scrollIntoViewSafe({
      container: body,
      element: target,
      block: 'center',
      behavior: 'instant',
    });
  }
  updateScrollHints();
}

watch([() => props.visibility, () => props.initialMessageId, outlineItems], () => {
  nextTick(() => scrollToInitialMessage());
}, { immediate: true });

watch(peekMessageId, () => {
  nextTick(() => updateScrollHints());
});

function togglePeek({ messageId }: { messageId: MessageId }) {
  const currentPeekMessageId = peekMessageId.value;
  if (currentPeekMessageId === messageId) {
    peekMessageId.value = undefined;
    return;
  }
  peekMessageId.value = messageId;
}

function formatRole({ role }: { role: OutlineRole }) {
  switch (role) {
  case 'user':
    return lazyStrings.ConversationOutlineOverlay__you();
  case 'assistant':
    return lazyStrings.ConversationOutlineOverlay__ai();
  case 'system':
    return lazyStrings.ConversationOutlineOverlay__system();
  case 'tool':
    return lazyStrings.ConversationOutlineOverlay__tool();
  default: {
    const _ex: never = role;
    return _ex;
  }
  }
}

function roleClass({ role }: { role: OutlineRole }) {
  switch (role) {
  case 'user':
    return "text-blue-600 dark:text-blue-400";
  case 'assistant':
    return "text-emerald-600 dark:text-emerald-400";
  case 'system':
    return "text-purple-600 dark:text-purple-400";
  case 'tool':
    return "text-amber-600 dark:text-amber-400";
  default: {
    const _ex: never = role;
    return _ex;
  }
  }
}

defineExpose({
  ...((__BUILD_MODE_IS_TEST__ && {
    TEST_ONLY: {
      // Export internal state and logic used only for testing here. Do not reference these in production logic.
    },
  }) || {}),
});

import "virtual:naidan-tailwind-css-module/0963f1f2efd282a3155bf2baaf9ccb2b9bcb9e9a0bfce29d1ec552f2fc67b37d.js";
import "virtual:naidan-tailwind-css-module/1fc352e4f4d158272aef0d689b35af08e47e1a0cb1f86097dd62891672898169.js";
import "virtual:naidan-tailwind-css-module/2975b9302e28f93816dc2fb62a193233f66bd2f685a602c3638b304ddbea4ea9.js";
import "virtual:naidan-tailwind-css-module/2e77395f19e41bda71e499828d218f01eec6b8fcb792169da7dca4774cfd4283.js";
import "virtual:naidan-tailwind-css-module/56e4373f55f359f04f7e389d21fb97c53c3d3909904d57e24636fcec24252a4b.js";
import "virtual:naidan-tailwind-css-module/700b077281bd84c9f3612edff619ee6b9e621e5164524877c3ea8a358e00d1e3.js";
import "virtual:naidan-tailwind-css-module/af0ebd838ed0f75f9c1c8df1ca63a57ac9fd4d3cb266d7bc6aac6cb49ee1c94e.js";
import "virtual:naidan-tailwind-css-module/ebecc4fd674ef82f183437255486fe38e6831e60d5730478c48be6aabd6a8f8f.js";
</script>

<template>
  <Transition name="dropdown">
    <div
      v-if="visibility === 'visible'"
      tw-class="absolute inset-0 z-40"
      data-testid="conversation-outline-overlay"
    >
      <div
        tw-class="absolute inset-0 bg-black/10 backdrop-blur-[1px] transition-opacity dark:bg-black/30"
        aria-hidden="true"
        data-testid="conversation-outline-backdrop"
        @click="emit('close')"
      />
      <div
        :tw-class="['absolute left-3 right-3 top-3 overflow-hidden rounded-xl border border-gray-200/80 bg-white/95 shadow-2xl backdrop-blur-md transition-[max-height] duration-150 ease-out dark:border-gray-700 dark:bg-gray-900/95', twClasses(outlineMaxHeightClass)]"
        data-testid="conversation-outline-panel"
        @click.stop
      >
        <div tw-class="flex items-center justify-between border-b border-gray-100 px-3 py-2 dark:border-gray-800">
          <div tw-class="flex items-center gap-2 text-xs font-bold uppercase tracking-wider text-gray-500 dark:text-gray-400">
            <ListIcon tw-class="h-4 w-4" />
            <span>{{ lazyStrings.ConversationOutlineOverlay__conversation_outline() }}</span>
          </div>
          <button
            @click="emit('close')"
            tw-class="rounded-lg p-1 text-gray-400 transition-colors hover:bg-gray-100 hover:text-gray-700 dark:hover:bg-gray-800 dark:hover:text-gray-200"
            :title="lazyStrings.ConversationOutlineOverlay__close_conversation_outline()"
            data-testid="close-conversation-outline-button"
          >
            <XIcon tw-class="h-4 w-4" />
          </button>
        </div>
        <div tw-class="relative">
          <div
            ref="outlineBody"
            @scroll="updateScrollHints()"
            :tw-class="['overflow-y-auto py-1 transition-[max-height] duration-150 ease-out', twClasses(outlineBodyMaxHeightClass)]"
            data-testid="conversation-outline-body"
          >
            <div
              v-for="item in outlineItems"
              :key="idToRaw({ id: item.id })"
              tw-class="border-b border-gray-100 last:border-b-0 dark:border-gray-800"
              data-testid="conversation-outline-item"
              :data-outline-message-id="idToRaw({ id: item.id })"
            >
              <div tw-class="grid grid-cols-[2.25rem_2.5rem_minmax(0,1fr)_2rem] items-center gap-1.5 px-3 py-2 text-sm transition-colors hover:bg-blue-50 dark:hover:bg-blue-900/20">
                <button
                  @click="emit('select-message', item.id)"
                  tw-class="contents text-left"
                  data-testid="conversation-outline-jump-button"
                >
                  <span tw-class="font-mono text-xs text-gray-400">{{ String(item.index).padStart(2, '0') }}</span>
                  <span
                    :tw-class="['text-xs font-bold uppercase tracking-wider', twClasses(roleClass({ role: item.role }))]"
                  >
                    {{ formatRole({ role: item.role }) }}
                  </span>
                  <span tw-class="truncate text-gray-700 dark:text-gray-200">{{ item.preview }}</span>
                </button>
                <button
                  @click="togglePeek({ messageId: item.id })"
                  :tw-class="['rounded-lg p-1 text-gray-400 transition-colors hover:bg-white hover:text-blue-600 dark:hover:bg-gray-800 dark:hover:text-blue-400', peekMessageId === item.id ? 'text-blue-600 dark:text-blue-400' : '']"
                  :title="lazyStrings.ConversationOutlineOverlay__peek()"
                  data-testid="conversation-outline-peek-button"
                >
                  <EyeIcon tw-class="h-4 w-4" />
                </button>
              </div>
              <Transition
                tw-enter-active-class="transition duration-150 ease-out"
                tw-enter-from-class="-translate-y-1 opacity-0"
                tw-enter-to-class="translate-y-0 opacity-100"
                tw-leave-active-class="transition duration-100 ease-in"
                tw-leave-from-class="translate-y-0 opacity-100"
                tw-leave-to-class="-translate-y-1 opacity-0"
              >
                <div
                  v-if="peekMessageId === item.id"
                  tw-class="mx-3 mb-3 max-h-72 overflow-y-auto rounded-lg border border-gray-100 bg-white dark:border-gray-800 dark:bg-gray-950/60"
                  data-testid="conversation-outline-peek"
                >
                  <MessageItem
                    :chat-id="props.chatId"
                    :message="item.node"
                    :part-content="item.partContent"
                    :flow="{ position: 'standalone', nesting: 'none' }"
                    :mode="'content'"
                    :siblings="[]"
                    :can-generate-image="false"
                    :is-processing="false"
                    :is-generating="false"
                    :available-image-models="[]"
                    :is-first-in-node="true"
                    :is-last-in-node="true"
                    :is-first-in-turn="true"
                    @fork="() => {}"
                    @edit="() => {}"
                    @switch-version="() => {}"
                    @regenerate="() => {}"
                    @abort="() => {}"
                  />
                </div>
              </Transition>
            </div>
          </div>
          <div
            v-if="topScrollHintVisibility === 'visible'"
            tw-class="pointer-events-none absolute inset-x-0 top-0 h-8 bg-gradient-to-b from-white/95 to-transparent dark:from-gray-900/95"
            data-testid="conversation-outline-scroll-hint-top"
          ></div>
          <div
            v-if="bottomScrollHintVisibility === 'visible'"
            tw-class="pointer-events-none absolute inset-x-0 bottom-0 h-10 bg-gradient-to-t from-white/95 to-transparent dark:from-gray-900/95"
            data-testid="conversation-outline-scroll-hint-bottom"
          ></div>
        </div>
      </div>
    </div>
  </Transition>
</template>
